bool Panel::highlight(QJsonObject page,semantic::Selection selection,unsigned selectedColor,bool existing){if(!canLeave()||!selection||selectedColor<1||selectedColor>7)return false;if(!open_){shown_=backdrop_;markedTop_=0;}++revealSceneEpoch_;notePresence_.reset();mode_=Mode::Highlight;textView_=false;textOffset_=0;page_=std::move(page);selection_=selection->data;color_=selectedColor;source_={};tomRequest_={};close_=closeAfterSave_=closeDeferred_=confirmDelete_=sourceColor_=false;open_=true;followUps_.clear();highlightPending_=true;bool ok=send({{"op","native.highlight"},{"page",page_},{"selection",selection_},{"color",styled::colorId(color_)},{"existing",existing}});paint();mark();reset_=true;return ok;}
void Panel::requestSource(QJsonObject anchor){int target=sourcePage(anchor,page_);if(target<0||!library::validHash(anchor["pageId"].toString())){source_={};notice_="Source changed — the note is kept";return;}source_=std::move(anchor);sourceTarget_=target;}
// Damage the sheet in quarter-screen bands so updates stay regional.
void Panel::mark(){int top=std::clamp(std::min(sheetTop_,markedTop_)-8,0,2160);markedTop_=sheetTop_; /* the sheet, plus what a size change uncovers */
 auto bands=[&]{damageCount_=0;for(int y=top;y<2160&&damageCount_<damage_.size();y+=520)damage_[damageCount_++]={0,y,1620,std::min(2160,y+520)};if(keyboard_.active()&&damageCount_<damage_.size())damage_[damageCount_++]={0,ux::TextInput::Panel.y0,1620,std::min(2160,ux::TextInput::Panel.y0+520)};};
 // Only what changed (the save state, a button, one row), appended to damage not yet taken; never the whole
 // sheet for a saved stroke. Without a previous paper (first paint) the sheet bands are refreshed.
 if(shown_.size()!=paper_.size())bands();
 else{std::array<spike::Rect,5> changed;const unsigned n=ux::changedRegions(shown_,paper_,1620,2160,1632,0,changed);for(unsigned i=0;i<n;++i){if(damageCount_>=damage_.size()){bands();break;}damage_[damageCount_++]=changed[i];}}
 shown_=paper_;}
void Panel::keyboard(QString value,QString title,QJsonObject command,unsigned limit){keyboardCommand_=std::move(command);keyboard_.open(std::move(value),std::move(title),limit);canvas_.enable(false);}
