  m.favorites=favorites_!=nullptr&&!note.isEmpty();m.favorite=starred(note);m.pen=ib::Instrument(unsigned(style_.tool));m.width=unsigned(style_.width);m.picker=picker_;m.canUndo=m.canRedo=!m.busy;m.empty=note["strokes"].toArray().isEmpty()&&note["text"].toString().isEmpty()&&!canvas_.unsaved();
  {const auto excerpt=note["anchor"].toObject()["excerpt"].toString().simplified();const QString where=target>=0?QString(" \u00b7 p. %1").arg(target+1):QString();
   m.context=utf8(m.unresolved?QString("Source changed \u2014 the note is kept"):!excerpt.isEmpty()?QString("Linked passage")+where:QString("Page note")+where);} /* the passage itself is the quoted line below */
