bool Panel::advanceClose(){if(!closeDeferred_||playback_.active()||finishingPlayback_||contact()||runtime_.unsaved()||view_.busy||pendingCommand_||!followUps_.empty())return false;
 if(mode_!=Mode::Note||!view_.error.isEmpty()||view_.note.isEmpty()||view_.note["minimized"].toBool()){close_=true;closeDeferred_=false;return true;}
 if(!send({{"op","note.minimized"},{"value",true}}))return false;closeDeferred_=false;closeAfterSave_=true;return true;}
bool Panel::keep(const QJsonObject& n)const{using F=ib::notes::Filter;const bool linked=!n["highlight"].toString().isEmpty();
 return filter_==F::All||(filter_==F::Linked&&linked)||(filter_==F::Pages&&!linked)||(filter_==F::Favorites&&starred(n))||(filter_==F::Tom&&isTom(n));}
